use fs2::FileExt;
use sha2::{Digest, Sha256};
use std::fs;
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use tempfile::NamedTempFile;

use super::entry::CacheEntry;

/// Guard that releases an advisory file lock when dropped.
pub struct CacheLockGuard {
    _file: fs::File,
}

/// Storage for cached templates.
pub struct CacheStore {
    /// Root directory for cache.
    root: PathBuf,
}

impl CacheStore {
    /// Create a new cache store.
    pub fn new(root: impl Into<PathBuf>) -> Self {
        Self { root: root.into() }
    }

    /// Get the cache root directory.
    pub fn root(&self) -> &Path {
        &self.root
    }

    /// Ensure the cache directory exists.
    fn ensure_dir(&self) -> Result<()> {
        fs::create_dir_all(&self.root)
            .with_context(|| format!("Failed to create cache directory {:?}", self.root))
    }

    /// Atomically write content to a path via temp file + rename.
    ///
    /// Creates a temporary file in the same directory as `path`, writes the
    /// content, then renames it into place. On POSIX systems `rename(2)` is
    /// atomic, so readers never see a partial write.
    fn atomic_write(&self, path: &Path, content: &[u8]) -> Result<()> {
        let dir = path.parent().unwrap_or(path);
        let mut tmp = NamedTempFile::new_in(dir)
            .with_context(|| format!("Failed to create temp file in {:?}", dir))?;
        tmp.write_all(content)?;
        tmp.persist(path)
            .with_context(|| format!("Failed to persist cache file to {:?}", path))?;
        Ok(())
    }

    /// Acquire an exclusive advisory lock for a cache entry.
    ///
    /// Returns a guard that releases the lock on drop. Hold this while
    /// performing multi-step writes (content + metadata) to prevent
    /// concurrent processes from interleaving their operations.
    pub fn lock_entry(&self, source_id: &str, template_name: &str) -> Result<CacheLockGuard> {
        self.ensure_dir()?;
        let lock_path = self
            .content_path(source_id, template_name)
            .with_extension("lock");
        let lock_file = fs::OpenOptions::new()
            .create(true)
            .write(true)
            .truncate(true)
            .open(&lock_path)
            .with_context(|| format!("Failed to open lock file {:?}", lock_path))?;
        lock_file
            .lock_exclusive()
            .with_context(|| format!("Failed to acquire cache lock on {:?}", lock_path))?;
        Ok(CacheLockGuard { _file: lock_file })
    }

    /// Get the path for storing an entry's content.
    pub fn content_path(&self, source_id: &str, template_name: &str) -> PathBuf {
        let key = format!("{}:{}", source_id, template_name);
        let hash = Sha256::digest(key.as_bytes());
        let hash_str = hex::encode(&hash[..16]);
        self.root.join(hash_str)
    }

    /// Get the metadata file path for an entry.
    fn metadata_path(&self, source_id: &str, template_name: &str) -> PathBuf {
        self.content_path(source_id, template_name)
            .with_extension("meta.json")
    }

    /// Atomically write content to a cache entry's content file.
    ///
    /// Callers performing a multi-step update (content + metadata) should
    /// hold a [`CacheLockGuard`] from [`lock_entry`] for the duration.
    pub fn atomic_write_content(
        &self,
        source_id: &str,
        template_name: &str,
        content: &str,
    ) -> Result<()> {
        let content_path = self.content_path(source_id, template_name);
        self.atomic_write(&content_path, content.as_bytes())
    }

    /// Store content and return a cache entry.
    ///
    /// Acquires a per-entry lock and writes both content and metadata
    /// atomically so concurrent processes cannot corrupt the cache.
    pub fn store(
        &self,
        source_id: &str,
        template_name: &str,
        content: &str,
        ttl_seconds: u64,
    ) -> Result<CacheEntry> {
        self.ensure_dir()?;

        let _lock = self.lock_entry(source_id, template_name)?;

        let content_path = self.content_path(source_id, template_name);
        self.atomic_write(&content_path, content.as_bytes())?;

        let entry = CacheEntry::new(source_id, template_name, &content_path, ttl_seconds)
            .with_size(content.len() as u64);

        self.save_metadata(&entry)?;

        Ok(entry)
    }

    /// Load a cached entry's metadata.
    ///
    /// Reads directly and handles `NotFound` instead of checking `exists()`
    /// first, avoiding TOCTOU races with concurrent removals.
    pub fn load(&self, source_id: &str, template_name: &str) -> Result<Option<CacheEntry>> {
        let meta_path = self.metadata_path(source_id, template_name);

        match fs::read_to_string(&meta_path) {
            Ok(json) => {
                let entry: CacheEntry = serde_json::from_str(&json).with_context(|| {
                    format!("Corrupted cache metadata at {:?}", meta_path)
                })?;
                Ok(Some(entry))
            }
            Err(e) if e.kind() == io::ErrorKind::NotFound => Ok(None),
            Err(e) => {
                Err(e).with_context(|| format!("Failed to read cache metadata {:?}", meta_path))
            }
        }
    }

    /// Read the cached content.
    pub fn read_content(&self, entry: &CacheEntry) -> Result<String> {
        fs::read_to_string(&entry.content_path).with_context(|| {
            format!(
                "Failed to read cached content from {:?}",
                entry.content_path
            )
        })
    }

    /// Save entry metadata atomically.
    fn save_metadata(&self, entry: &CacheEntry) -> Result<()> {
        let meta_path = self.metadata_path(&entry.source_id, &entry.template_name);
        let json = serde_json::to_string_pretty(entry)?;
        self.atomic_write(&meta_path, json.as_bytes())
    }

    /// Update an entry's metadata (e.g., after revalidation).
    ///
    /// Uses atomic write internally. Callers performing multi-step updates
    /// (content + metadata) should hold a [`CacheLockGuard`].
    pub fn update(&self, entry: &CacheEntry) -> Result<()> {
        self.save_metadata(entry)
    }

    /// Remove a cached entry.
    ///
    /// Handles files that are already gone (concurrent removal) gracefully
    /// instead of checking `exists()` first.
    pub fn remove(&self, source_id: &str, template_name: &str) -> Result<bool> {
        let content_path = self.content_path(source_id, template_name);
        let meta_path = self.metadata_path(source_id, template_name);
        let lock_path = self
            .content_path(source_id, template_name)
            .with_extension("lock");

        let mut removed = false;

        match fs::remove_file(&content_path) {
            Ok(()) => removed = true,
            Err(e) if e.kind() == io::ErrorKind::NotFound => {}
            Err(e) => {
                return Err(e)
                    .with_context(|| format!("Failed to remove cache content {:?}", content_path))
            }
        }

        match fs::remove_file(&meta_path) {
            Ok(()) => removed = true,
            Err(e) if e.kind() == io::ErrorKind::NotFound => {}
            Err(e) => {
                return Err(e)
                    .with_context(|| format!("Failed to remove cache metadata {:?}", meta_path))
            }
        }

        // Best-effort cleanup of the lock file.
        let _ = fs::remove_file(&lock_path);

        Ok(removed)
    }

    /// List all cached entries.
    pub fn list(&self) -> Result<Vec<CacheEntry>> {
        self.ensure_dir()?;

        let mut entries = Vec::new();

        for entry in fs::read_dir(&self.root)? {
            let entry = entry?;
            let path = entry.path();

            if path.extension().is_some_and(|e| e == "json") {
                if let Ok(json) = fs::read_to_string(&path) {
                    if let Ok(cache_entry) = serde_json::from_str::<CacheEntry>(&json) {
                        entries.push(cache_entry);
                    }
                }
            }
        }

        entries.sort_by(|a, b| b.metadata.cached_at.cmp(&a.metadata.cached_at));
        Ok(entries)
    }

    /// Clear all cached entries.
    pub fn clear(&self) -> Result<usize> {
        let entries = self.list()?;
        let count = entries.len();

        for entry in entries {
            let _ = self.remove(&entry.source_id, &entry.template_name);
        }

        Ok(count)
    }

    /// Get total cache size in bytes.
    pub fn total_size(&self) -> Result<u64> {
        let entries = self.list()?;
        Ok(entries.iter().map(|e| e.metadata.size_bytes).sum())
    }
}

